// [要インスタンス確認] $input.all() は一般的なCodeノードAPIの想定であり未検証。
const items = $input.all();

const rssItems = items.filter(i => i.json._recordType === 'rss_item');
const logItems = items.filter(i => i.json._recordType === 'log_entry');

const alreadyDistributed = new Set(
  logItems.map(i => i.json.articleUrl).filter(Boolean)
);

const newItems = rssItems.filter(i => !alreadyDistributed.has(i.json.articleUrl));

// 冪等性のため、同一実行内での重複URL（複数ソースが同じ記事を配信している場合）も除去する
const seen = new Set();
const dedupedNewItems = [];
for (const item of newItems) {
  const url = item.json.articleUrl;
  if (url && !seen.has(url)) {
    seen.add(url);
    dedupedNewItems.push(item);
  }
}

return dedupedNewItems;

// runOnceForAllItems モードのため、入力0件でも必ず1回実行される想定。[要インスタンス確認]
const items = $input.all();
return [{ json: { newArticleCount: items.length } }];

// [要インスタンス確認] $('ノード名').all() は一般的な想定であり未検証。
// 直前ノード（If）の出力ではなく、Dedup結果ノードを直接参照する（Ifノードを通過した時点の$inputは件数チェック用の1件のみのため）。
const items = $('Code: Deduplicate Against Log').all();

const targetLanguage = $('Set: Config (Sources & Distribution Options)').first().json.digestLanguage || 'en';

const articles = items.map(i => ({
  title: i.json.articleTitle,
  url: i.json.articleUrl,
  publishedAt: i.json.publishedAt,
  sourceName: i.json.sourceName
}));

const systemInstruction = [
  'You are summarizing Japanese government/regulatory news articles for a non-Japanese-speaking business audience.',
  'For EACH article provided, produce: (1) a concise summary (3-5 sentences, do NOT reproduce the full article text),',
  `(2) a translation of that summary into ${targetLanguage},`,
  '(3) the original title, source URL, and published date EXACTLY as provided (do not omit or alter them).',
  'Do not fabricate facts not present in the article metadata provided. If the provided data is insufficient to summarize confidently, say so explicitly rather than guessing.',
  'Return ONLY a JSON array (no surrounding text, no code fences), one object per article, with keys: title, url, publishedAt, sourceName, summaryTranslated, language.'
].join(' ');

// Anthropic Messages API形式（2026-08-15、公式ドキュメント・PUB-001等の既存実装で確認済みの形式）：
// system は独立フィールド、messagesはuser/assistantのみ。
const requestBody = {
  model: 'claude-haiku-4-5',
  max_tokens: 16000,
  system: systemInstruction,
  messages: [
    { role: 'user', content: JSON.stringify(articles) }
  ]
};

return [{ json: { requestBody, articleCountBeforeAi: articles.length } }];

// Anthropic Messages APIの応答形式（content: [{type:'text', text:'...'}], ...）で解析する（2026-08-15更新）。
const response = $input.first().json;

let parsed;
try {
  const block = Array.isArray(response?.content) ? response.content.find(b => b.type === 'text') : null;
  const rawText = block?.text ?? null;
  if (!rawText) {
    throw new Error('AI応答からcontentを取得できませんでした。レスポンス構造を確認してください。detail=' + JSON.stringify(response).slice(0, 500));
  }
  let text = rawText.trim();
  text = text.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  parsed = JSON.parse(text);
} catch (e) {
  // パース失敗時はエラーとして扱い、ワークフローを停止させる（不完全なダイジェスト配信を防ぐ）
  throw new Error(`AI応答のパースに失敗しました: ${e.message}`);
}

if (!Array.isArray(parsed)) {
  throw new Error('AI応答が期待する配列形式ではありません。');
}

return parsed.map(article => ({ json: article }));

// [要インスタンス確認] $('ノード名').first() は一般的な想定であり未検証。
const items = $input.all();
const editedBy = $('Set: Config (Sources & Distribution Options)').first().json.editedBySubjectLabel || 'This workflow operator';
const nowIso = new Date().toISOString();

const lines = items.map(i => {
  const a = i.json;
  return `- ${a.summaryTranslated}\n  Source: ${a.sourceName} | ${a.title} | ${a.publishedAt}\n  ${a.url}`;
});

const disclaimer = [
  '---',
  `This digest was automatically summarized and translated by AI (executed by: ${editedBy}) on ${nowIso}.`,
  'It is not a substitute for reading the original source. Please verify important details against the original article before making decisions.',
  'Source titles, URLs, and publish dates above are preserved from the original RSS feeds.'
].join('\n');

const digestText = [
  `Japan Regulatory & Government News Digest - ${nowIso.slice(0, 10)}`,
  '',
  ...lines,
  '',
  disclaimer
].join('\n');

const articles = items.map(i => ({ articleUrl: i.json.url, sourceName: i.json.sourceName }));

return [{ json: { digestText, articleCount: items.length, articles } }];

// [要インスタンス確認] $('ノード名').first() は一般的な想定であり未検証。
const assembled = $('Code: Assemble Digest').first().json;
const nowIso = new Date().toISOString();
const articles = Array.isArray(assembled.articles) ? assembled.articles : [];

if (articles.length === 0) {
  // 想定外だが、空の場合は書き込み対象なしとして空配列を返す（後続でエラーにしない）
  return [];
}

return articles.map(a => ({
  json: {
    articleUrl: a.articleUrl,
    sourceName: a.sourceName,
    distributedAt: nowIso
  }
}));
